settings.custom_liquid:
{% comment %}
  Shipping Availability Display
  Clean version - no background, customizable color
{% endcomment %}

<style>
  .shipping-text-display {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-size: 14px;
    line-height: 1.4;
    margin: 4px 0;
    padding: 0;
  }

  .shipping-text-display__dot {
display: inline-block !important;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background-color: var(--shipping-color, #10B981);
    flex-shrink: 0;
  }

  .shipping-text-display__text {
    font-weight: 500;
    color: var(--shipping-text-color, inherit);
  }

  @media (max-width: 749px) {
    .shipping-text-display {
      font-size: 13px;
      gap: 6px;
    }

    .shipping-text-display__dot {
      width: 8px;
      height: 8px;
    }
  }
</style>

<div class="shipping-text-display">
  <div class="shipping-text-display__dot"></div>
  <span class="shipping-text-display__text">
   In 1 - 2 Werktagen bei dir - Garantiert vor Weihnachten da -
  </span>
</div>

<script>
  // To customize the dot color, add this to your theme's CSS or use inline style:
  // <style>
  //   :root {
  //     --shipping-color: #your-color-here; /* Green dot color */
  //     --shipping-text-color: #your-text-color; /* Text color */
  //   }
  // </style>
</script>
